#pragma once
#include <fstream>
#include <string>
#include "EventTransport.hpp"

namespace sensor_platform {
// Internal numeric plan generated by the Python JSON experiment CLI.
void runExperiment(sensor_sandbox::RunId runId, const std::string& path, const EventSink& sink);

struct ObservationOptions {
    std::string metrics;
    int delayMs{};
    std::size_t pauseAfter{};
    int pauseMs{};
};

// Wall-clock instrumentation stays outside domain events. All processes must share a host clock.
class Observation {
public:
    explicit Observation(const ObservationOptions& options);
    void beforeConsume();
    void mark(const char* phase, std::uint64_t sequence);
private:
    ObservationOptions options_;
    std::ofstream output_;
    std::size_t consumed_{};
};
}
